export function ecommercePage(){return `<section class="commerce-intro"><div class="overline">КАТАЛОГ / E-COMMERCE</div><h1>E-commerce</h1><p>Данные о товарах, ценах, отзывах и продавцах. Выберите площадку — все её инструменты собраны в одном продукте.</p></section><article class="amazon-feature"><div class="amazon-mark" aria-hidden="true">a<span>⌣</span></div><div><div class="overline">ПЕРВЫЙ ПРОДУКТ РАЗДЕЛА</div><h2>Amazon</h2><p>Ищите товары, сравнивайте цены, собирайте отзывы и изучайте продавцов. Расскажите ассистенту, что хотите узнать. Он уточнит детали и подготовит предложение.</p><div class="amazon-tags"><span>Товары</span><span>Отзывы</span><span>Продавцы</span><span>Бестселлеры</span><span>Категории и бренды</span></div><a class="primary" href="#product/amazon">Обсудить задачу →</a></div></article><section class="commerce-note"><h2>Одна площадка — один продукт</h2><p>Поиск, карточки, отзывы и данные продавцов доступны из одного рабочего пространства. Не нужно выбирать между дублирующими наборами данных. Сейчас первым собираем Amazon; другие площадки появятся после подключения и проверки.</p></section>`;}
export function amazonHome(){return `<section class="commerce-intro"><div class="overline">AFFSIWEN / КАТАЛОГ ПРОДУКТОВ</div><h1>Данные нужной площадки.<br><em>В одном продукте.</em></h1><p>Выберите раздел и площадку, опишите задачу и получите нужную выгрузку внутри Affsiwen. Начинаем с Amazon: товары, цены, отзывы и продавцы.</p></section><section class="commerce-department"><div><div class="overline">РАЗДЕЛ 01</div><h2>E-commerce</h2><p>Изучайте ассортимент, предложения и обратную связь покупателей.</p><a href="#e-commerce" class="secondary">Все продукты раздела →</a></div><article class="amazon-feature"><div class="amazon-mark" aria-hidden="true">a<span>⌣</span></div><div><h2>Amazon</h2><p>Расскажите о своей задаче. Ассистент подберёт данные и покажет цену до запуска.</p><a class="primary" href="#product/amazon">Обсудить задачу →</a><small>Запрос и выдача в вашем рабочем пространстве</small></div></article></section><section class="commerce-note"><h2>Как это работает</h2><ol class="journey-steps"><li><span class="step-no">01</span><h3>Выберите площадку</h3><p>Каждый продукт объединяет инструменты одной площадки.</p></li><li><span class="step-no">02</span><h3>Задайте запрос</h3><p>Напишите ассистенту, что хотите узнать. Он задаст нужные уточнения.</p></li><li><span class="step-no">03</span><h3>Проверьте предложение</h3><p>Состав результата, объём и цена понятны до запуска.</p></li><li><span class="step-no">04</span><h3>Получите данные</h3><p>Результат в Affsiwen и выгрузка CSV. Статус реального запуска указан в продукте.</p></li></ol></section>`;}
const euro=c=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'EUR'}).format(c/100);
export function amazonPage({connection=null,messages=[],answer=null,plan=null,quote=null,result=null,error='',pending=false,text='',mode='preview',image=null}={}){
 const conversational=messages.length>0,preview=(connection?.assistantMode||mode)!=='llm';
 return `<section class="amazon-chat-heading"><a class="quiet-link" href="#e-commerce">E-commerce / Amazon</a><div class="overline">AMAZON · AFFSIWEN</div><h1>Что хотите узнать<br>об Amazon?</h1><p>Опишите задачу. Я уточню детали, подберу нужные данные и покажу предложение с ценой.</p><div class="chat-mode"><span class="pill ${preview?'amber':'green'}">${preview?'Демо диалога':'AI-ассистент'}</span><span>${preview?'Сценарий знакомства с продуктом. Свободный AI-диалог ещё не подключён.':'Ассистент помогает с запросом. Запуск — только после вашего подтверждения.'}</span></div></section><section class="amazon-chat-shell" aria-label="Ассистент Amazon"><div class="amazon-chat-top"><span><i class="chat-orb">a</i> Ваш помощник по Amazon</span>${conversational?'<button class="text-button" data-action="amazon-reset">Новый запрос</button>':''}</div><div class="amazon-transcript" aria-live="polite" aria-busy="${pending}">${conversational?messages.map(m=>`<article class="chat-bubble ${m.role==='user'?'from-user':'from-assistant'}"><small>${m.role==='user'?'Вы':'Affsiwen'}</small>${m.hasImage?'<small class="chat-photo-note">Фото приложено · сохранено его описание</small>':''}<p>${esc(m.content)}</p></article>`).join(''):`<article class="chat-bubble from-assistant"><small>Affsiwen</small><p>Расскажите, что решаете: выбираете товар для магазина, сравниваете предложения конкурентов или собираете отзывы покупателей?</p><p>Я помогу сформулировать запрос. До запуска вы увидите, что получите и сколько это будет стоить.</p></article>`}${pending?`<article class="chat-bubble from-user"><small>Вы</small><p>${esc(text)}</p></article><div class="chat-thinking" role="status">Готовлю следующий шаг…</div>`:''}</div>${!pending&&!plan?`<div class="chat-suggestions">${(answer?.options?.length?answer.options:!conversational?['Сравнить товары по ключевой фразе','Собрать отзывы о товаре','Изучить продавца']:[]).map(v=>`<button data-action="amazon-suggestion" data-value="${esc(v)}">${esc(v)} →</button>`).join('')}</div>`:''}${plan?`<section class="amazon-offer"><div class="overline">ВАШЕ ПРЕДЛОЖЕНИЕ</div><div class="offer-heading"><h2>${esc(plan.title)}</h2><div class="offer-price">${quote?euro(quote.priceCents):'Цена готовится'}<small>${quote?'за этот запрос · предварительно':'оплата пока недоступна'}</small></div></div><p class="offer-brief">${esc(plan.value)} · Amazon ${esc(plan.market)}</p><ul><li>До ${plan.limit} записей. Фактическое количество зависит от доступных данных.</li><li>${esc(plan.columns.join(', '))}.</li><li>Таблица в Affsiwen и файл CSV.</li></ul><p class="fine">${esc(quote?.notice||'Состав запроса подготовлен. Стоимость подтвердим после расчёта реальных расходов; сейчас ничего не списываем.')}</p><button class="primary full" data-action="amazon-demo">Посмотреть пример результата</button><p class="fine">Оплата и реальный сбор пока не включены. Изменить задачу или объём можно сообщением ниже.</p></section>`:''}${result?`<section class="amazon-result"><h2>Так будет выглядеть выдача</h2><span class="pill amber">ДЕМО · ВЫМЫШЛЕННЫЕ ДАННЫЕ</span><div class="sample-table"><table><caption>${esc(result.title)} · ${result.rows.length} демонстрационных строк</caption><thead><tr>${Object.keys(result.rows[0]||{}).map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${result.rows.map(r=>`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><a class="secondary" href="/api/amazon/export">Скачать демо CSV</a></section>`:''}${error?`<div class="amazon-error" role="alert">${esc(error)}</div>`:''}<form id="amazon-chat" class="amazon-composer"><label for="amazon-message">Ваше сообщение</label>${image?`<div class="chat-photo-preview"><img src="data:${esc(image.mediaType)};base64,${esc(image.data)}" alt="Фото к вашему запросу"><span>Фото готово к отправке</span><button type="button" class="text-button" data-action="amazon-remove-image" ${pending?'disabled':''}>Убрать</button></div>`:''}<textarea id="amazon-message" name="message" required minlength="2" maxlength="2000" placeholder="Например: хочу сравнить 50 термобутылок на Amazon в Германии" ${pending?'disabled':''}>${pending?'':esc(text)}</textarea><div class="chat-upload"><label class="secondary">＋ Фото<input id="amazon-photo" type="file" accept="image/jpeg,image/png,image/webp" ${pending||preview?'disabled':''}></label><small>${preview?'Фото станет доступно после подключения AI.':'Одно фото JPEG, PNG или WebP. При отправке оно передаётся AI для ответа; в истории сохраняется описание.'}</small></div><div><small>Запуск сбора и оплата требуют отдельного подтверждения.</small><button class="primary" ${pending?'disabled':''}>${pending?'Отвечаю…':'Отправить ↑'}</button></div></form></section><section class="chat-how"><div><span>01</span><strong>Ваша задача</strong><p>Простыми словами, без выбора инструментов.</p></div><div><span>02</span><strong>Понятное предложение</strong><p>Результат, объём и сумма до запуска.</p></div><div><span>03</span><strong>Данные у вас</strong><p>Таблица и выгрузка в одном месте.</p></div></section>`;
}
